<script setup lang="ts">
import {useSlip,useWallet} from '../stores/store';import {fmt} from '../data/mock';import {useRouter} from 'vue-router';const slip=useSlip(),w=useWallet(),r=useRouter();
function place(){ if(!slip.items.length)return; if(slip.stake>w.balance){alert('Salio haitoshi / Insufficient balance');return} w.add(-slip.stake,'bet_stake'); const bets=JSON.parse(localStorage.getItem('mybets')||'[]'); bets.unshift({id:Date.now(),items:slip.items, stake:slip.stake, odds:slip.combined, payout:slip.payout,status:'Open'}); localStorage.setItem('mybets',JSON.stringify(bets)); slip.clear(); slip.open=false; r.push('/my-bets')};
</script>
<template><div :class="['slip',{open:slip.open}]"><h3>{{$t('betslip')}} ({{slip.items.length}})</h3><button v-if="slip.open" @click="slip.open=false">✕</button><div v-for="i in slip.items" :key="i.key">{{i.match}} — {{i.sel}} @ {{i.price.toFixed(2)}} <button @click="slip.toggle({id:i.matchId},i)">x</button></div><label>{{$t('stake')}}</label><input type="number" v-model.number="slip.stake"/><p>{{$t('potential')}}: <b class="gold">{{fmt(slip.payout)}}</b> (odds {{slip.combined.toFixed(2)}})</p><button @click="place">{{$t('place')}}</button></div></template>
